package deposit.service;

import deposit.common.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import org.neo4j.graphdb.Label;
import org.neo4j.graphdb.Node;

/** Receipt-owned bounded import result collections stored in the enclosing Neo4j transaction. */
final class ImportResultRepository {
    static final String FORMAT="deposit.import-result/1";
    static final int MAX_ENTRY_BYTES=32*1024, TEXT_CHUNK_BYTES=16*1024, PAGE_LIMIT=256, PAGE_BYTES=512*1024;
    private static final String ROOT="DepositImportResult", COLLECTION="DepositImportResultCollection", ENTRY="DepositImportResultEntry";
    private final RequestContext c;
    ImportResultRepository(RequestContext context){c=context;}

    Map<String,Object> save(String operationId,String kind,String planId,long revision,long expiresAt,Map<String,Object> data){
        String id=UUID.randomUUID().toString();Node root=c.tx.createNode(Label.label(ROOT));root.setProperty("id",id);root.setProperty("namespaceId",c.namespaceId);root.setProperty("actorId",c.actorId);root.setProperty("operationId",operationId);root.setProperty("kind",kind);root.setProperty("state",planId==null?"committed":"ready");root.setProperty("revision",revision);root.setProperty("expiresAt",expiresAt);if(planId!=null)root.setProperty("planId",planId);
        var collections=new TreeMap<String,Object>();var internal=new TreeMap<String,String>();var metadata=new LinkedHashMap<String,Object>();
        for(var entry:data.entrySet()){
            if(entry.getValue() instanceof Map<?,?> map){CollectionRef saved=saveCollection(id,entry.getKey(),"mapping",map);if(entry.getKey().startsWith("_"))internal.put(entry.getKey(),saved.id);else collections.put(entry.getKey(),saved.descriptor);}
            else if(entry.getValue() instanceof Collection<?> values){CollectionRef saved=saveCollection(id,entry.getKey(),"sequence",values);if(entry.getKey().startsWith("_"))internal.put(entry.getKey(),saved.id);else collections.put(entry.getKey(),saved.descriptor);}
            else metadata.put(entry.getKey(),entry.getValue());
        }
        if(!metadata.isEmpty())collections.put("metadata",saveCollection(id,"metadata","mapping",metadata).descriptor);
        root.setProperty("collections",Json.write(collections));root.setProperty("internalCollections",Json.write(internal));return envelope(root);
    }

    private CollectionRef saveCollection(String resultId,String name,String kind,Object input){
        String id=UUID.randomUUID().toString();Collection<?> values=kind.equals("mapping")?((Map<?,?>)input).entrySet(): (Collection<?>)input;long count=values.size();Node col=c.tx.createNode(Label.label(COLLECTION));col.setProperty("resultId",resultId);col.setProperty("id",id);col.setProperty("name",name);col.setProperty("kind",kind);col.setProperty("count",count);
        long position=0;var seen=new HashSet<String>();
        for(Object raw:values){String mapKey=null;Object keyDescriptor=null,value=raw;if(kind.equals("mapping")){var entry=(Map.Entry<?,?>)raw;Object key=entry.getKey();if(!(key instanceof String))throw new IllegalArgumentException("Import result mapping keys must be strings");mapKey=(String)key;String hash=hash(mapKey);if(!seen.add(hash+":"+mapKey))throw new IllegalArgumentException("Duplicate import result key");keyDescriptor=describe(resultId,mapKey);value=entry.getValue();}
            Object descriptor=describe(resultId,value);String encoded=Json.write(descriptor);if(encoded.getBytes(StandardCharsets.UTF_8).length>MAX_ENTRY_BYTES)throw new IllegalArgumentException("Import result entry exceeds the bounded segment size");Node row=c.tx.createNode(Label.label(ENTRY));row.setProperty("resultId",resultId);row.setProperty("collectionId",id);row.setProperty("position",position++);row.setProperty("value",encoded);if(mapKey!=null){row.setProperty("key",Json.write(keyDescriptor));row.setProperty("mapKeyHash",hash(mapKey));if(mapKey.getBytes(StandardCharsets.UTF_8).length<=MAX_ENTRY_BYTES/2)row.setProperty("mapKey",mapKey);row.setProperty("mapKeyLength",mapKey.getBytes(StandardCharsets.UTF_8).length);}
        }
        return new CollectionRef(id,Json.map("kind",kind,"count",count));
    }
    private record CollectionRef(String id,Map<String,Object> descriptor){}

    private Object describe(String resultId,Object value){
        if(value instanceof Map<?,?> map)return Json.map("type","mapping","collection",saveCollectionWithId(resultId,UUID.randomUUID().toString(),"mapping",map),"count",(long)map.size());
        if(value instanceof Collection<?> values)return Json.map("type","sequence","collection",saveCollectionWithId(resultId,UUID.randomUUID().toString(),"sequence",values),"count",(long)values.size());
        if(value instanceof String text){byte[] bytes=text.getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_ENTRY_BYTES/2){String collection=UUID.randomUUID().toString();Node col=c.tx.createNode(Label.label(COLLECTION));col.setProperty("resultId",resultId);col.setProperty("id",collection);col.setProperty("name",collection);col.setProperty("kind","sequence");long count=0;for(int start=0;start<bytes.length;){int end=Math.min(bytes.length,start+TEXT_CHUNK_BYTES);while(end<bytes.length&&(bytes[end]&0xc0)==0x80)end--;if(end==start)throw new IllegalArgumentException("Cannot segment UTF-8 text");String chunk=new String(bytes,start,end-start,StandardCharsets.UTF_8);Node row=c.tx.createNode(Label.label(ENTRY));row.setProperty("resultId",resultId);row.setProperty("collectionId",collection);row.setProperty("position",count++);row.setProperty("value",Json.write(Json.map("type","scalar","value",chunk)));start=end;}col.setProperty("count",count);return Json.map("type","text","collection",collection,"bytes",(long)bytes.length);}}
        return Json.map("type","scalar","value",value);
    }

    private String saveCollectionWithId(String resultId,String id,String kind,Object input){
        Collection<?> values=kind.equals("mapping")?((Map<?,?>)input).entrySet():(Collection<?>)input;Node col=c.tx.createNode(Label.label(COLLECTION));col.setProperty("resultId",resultId);col.setProperty("id",id);col.setProperty("name",id);col.setProperty("kind",kind);col.setProperty("count",(long)values.size());long position=0;var seen=new HashSet<String>();
        for(Object raw:values){String mapKey=null;Object value=raw,keyDescriptor=null;if(kind.equals("mapping")){var entry=(Map.Entry<?,?>)raw;if(!(entry.getKey() instanceof String key))throw new IllegalArgumentException("Import result mapping keys must be strings");mapKey=key;if(!seen.add(mapKey))throw new IllegalArgumentException("Duplicate import result key");keyDescriptor=describe(resultId,key);value=entry.getValue();}String encoded=Json.write(describe(resultId,value));if(encoded.getBytes(StandardCharsets.UTF_8).length>MAX_ENTRY_BYTES)throw new IllegalArgumentException("Import result entry exceeds the bounded segment size");Node row=c.tx.createNode(Label.label(ENTRY));row.setProperty("resultId",resultId);row.setProperty("collectionId",id);row.setProperty("position",position++);row.setProperty("value",encoded);if(mapKey!=null){row.setProperty("key",Json.write(keyDescriptor));row.setProperty("mapKeyHash",hash(mapKey));row.setProperty("mapKeyLength",mapKey.getBytes(StandardCharsets.UTF_8).length);if(mapKey.getBytes(StandardCharsets.UTF_8).length<=MAX_ENTRY_BYTES/2)row.setProperty("mapKey",mapKey);}}
        return id;
    }

    Map<String,Object> envelope(String resultId){Node root=find(ROOT,Map.of("id",resultId));if(root==null)c.fail("NOT_FOUND","Import result is unavailable");authorize(root);return envelope(root);}
    Map<String,Object> envelopeForPlan(String resultId,String planId,String namespaceId){Node root=find(ROOT,Map.of("id",resultId));if(root==null||!namespaceId.equals(root.getProperty("namespaceId"))||!planId.equals(root.getProperty("planId",null)))c.fail("NOT_FOUND","Import result is unavailable");Node receipt=find("DepositReceipt",Map.of("scope",namespaceId,"operationId",root.getProperty("operationId")));if(receipt==null||!resultId.equals(receipt.getProperty("importResultId",null)))c.fail("NOT_FOUND","Import result is unavailable");return envelope(root);}
    Map<String,Object> envelope(String resultId,String state){var value=new LinkedHashMap<>(envelope(resultId));value.put("state",state);return value;}
    Map<String,Object> envelope(String resultId,String state,long expiresAt){var value=new LinkedHashMap<>(envelope(resultId,state));value.put("expiresAt",expiresAt);return value;}
    private Map<String,Object> envelope(Node root){var result=Json.map("format",FORMAT,"resultId",root.getProperty("id"),"operationId",root.getProperty("operationId"),"kind",root.getProperty("kind"),"state",root.getProperty("state"),"namespaceId",root.getProperty("namespaceId"),"planId",root.getProperty("planId",null),"revision",root.getProperty("revision"),"expiresAt",root.getProperty("expiresAt"),"collections",Json.read((String)root.getProperty("collections")));return result;}

    Map<String,Object> page(Map<String,Object> request){BaseService.fields(request,"resultId","collection","cursor","limit");String resultId=RequestContext.uuid(request.get("resultId")),name=BaseService.string(request.get("collection"));Node root=requireRoot(resultId);authorize(root);Map<String,Object> specs=ValueCodec.map(Json.read((String)root.getProperty("collections")));Object rawSpec=specs.get(name);Node collection=find(COLLECTION,Map.of("resultId",resultId,"name",name));if(collection==null||rawSpec==null&&!name.equals(collection.getProperty("id")))c.fail("NOT_FOUND","Import result collection is unavailable");String kind=(String)collection.getProperty("kind");long count=((Number)collection.getProperty("count")).longValue();if(rawSpec!=null&&(!kind.equals(ValueCodec.map(rawSpec).get("kind"))||count!=((Number)ValueCodec.map(rawSpec).get("count")).longValue()))c.fail("RESOURCE_CORRUPT","Import result collection metadata differs");long start=0;Object rawLimit=request.get("limit");long limit=rawLimit==null?PAGE_LIMIT:BaseService.integer(rawLimit);if(limit<1||limit>PAGE_LIMIT)c.fail("VALIDATION_FAILED","Page limit is outside the supported range");if(request.get("cursor") instanceof String token){Map<String,Object> cursor=CursorCodec.decode(c,token);if(!resultId.equals(cursor.get("resultId"))||!name.equals(cursor.get("collection")))c.fail("VALIDATION_FAILED","Cursor belongs to a different result collection");start=((Number)cursor.get("position")).longValue();}
        if(start<0||start>count)c.fail("VALIDATION_FAILED","Invalid result cursor");String collectionId=(String)collection.getProperty("id");var rows=new ArrayList<Object>();long bytes=0,position=start;while(position<count&&rows.size()<limit){Node row=find(ENTRY,Map.of("resultId",resultId,"collectionId",collectionId,"position",position));if(row==null)c.fail("RESOURCE_CORRUPT","Import result segment is missing");String value=(String)row.getProperty("value");long size=value.getBytes(StandardCharsets.UTF_8).length;if(!rows.isEmpty()&&bytes+size>PAGE_BYTES)break;bytes+=size;Object descriptor=Json.read(value);if(kind.equals("mapping"))rows.add(Json.map("key",Json.read((String)row.getProperty("key")),"value",descriptor));else rows.add(descriptor);position++;}
        String next=position<count?CursorCodec.encode(c,Json.map("resultId",resultId,"collection",name,"position",position,"expires",System.currentTimeMillis()+86_400_000L)):null;return Json.map("format","deposit.import-result-page/1","resultId",resultId,"collection",name,"entries",rows,"nextCursor",next);
    }

    Map<String,Object> entry(Map<String,Object> request){
        BaseService.fields(request,"resultId","collection","key");String resultId=RequestContext.uuid(request.get("resultId")),name=BaseService.string(request.get("collection"));
        Node root=requireRoot(resultId);authorize(root);Map<String,Object> specs=ValueCodec.map(Json.read((String)root.getProperty("collections")));Object rawSpec=specs.get(name);
        Node collection=find(COLLECTION,Map.of("resultId",resultId,"name",name));
        if(collection==null||rawSpec!=null&& !"mapping".equals(ValueCodec.map(rawSpec).get("kind"))||rawSpec==null&& !"mapping".equals(collection.getProperty("kind")))c.fail("NOT_FOUND","Import result mapping is unavailable");
        String key=BaseService.string(request.get("key"));if(key.getBytes(StandardCharsets.UTF_8).length>MAX_ENTRY_BYTES/2)c.fail("VALIDATION_FAILED","Entry keys must fit the bounded lookup size; use page iteration for larger keys");
        Node row=lookup(collection,key);return row==null?Json.map("resultId",resultId,"collection",name,"found",false):Json.map("resultId",resultId,"collection",name,"found",true,"value",Json.read((String)row.getProperty("value")));
    }

    Map<String,Object> mappingView(String resultId,String name){Node collection=find(COLLECTION,Map.of("resultId",resultId,"name",name));if(collection==null){Node root=find(ROOT,Map.of("id",resultId));if(root!=null&&root.hasProperty("internalCollections")){Object id=ValueCodec.map(Json.read((String)root.getProperty("internalCollections"))).get(name);if(id instanceof String collectionId)collection=find(COLLECTION,Map.of("resultId",resultId,"id",collectionId));}}if(collection==null)return Map.of();String collectionId=(String)collection.getProperty("id");long count=((Number)collection.getProperty("count")).longValue();return new AbstractMap<>(){
        public Object get(Object key){if(!(key instanceof String text))return null;Node row=lookup(collectionId,resultId,text);return row==null?null:decodeValue((String)row.getProperty("value"));}
        public boolean containsKey(Object key){return key instanceof String text&&lookup(collectionId,resultId,text)!=null;}
        public int size(){return (int)Math.min(Integer.MAX_VALUE,count);}
        public Set<Entry<String,Object>> entrySet(){return new AbstractSet<>(){public int size(){return ImportResultRepository.this.size(count);}public Iterator<Entry<String,Object>> iterator(){return iteratorFor(collectionId,resultId);}};}
    };}
    private Iterator<Map.Entry<String,Object>> iteratorFor(String collectionId,String resultId){var rows=nodes(ENTRY,Map.of("resultId",resultId,"collectionId",collectionId));rows.sort(Comparator.comparingLong(n->((Number)n.getProperty("position")).longValue()));var iterator=rows.iterator();return new Iterator<>(){public boolean hasNext(){return iterator.hasNext();}public Map.Entry<String,Object> next(){Node row=iterator.next();return new AbstractMap.SimpleImmutableEntry<>(decodeKey(row),decodeValue((String)row.getProperty("value")));}};}
    private String decodeKey(Node row){if(row.hasProperty("mapKey"))return (String)row.getProperty("mapKey");Object raw=Json.read((String)row.getProperty("key"));if(!(raw instanceof Map<?,?> descriptor))throw new IllegalStateException("Invalid import result mapping key");if("scalar".equals(descriptor.get("type"))&&descriptor.get("value") instanceof String text)return text;if(!"text".equals(descriptor.get("type")))throw new IllegalStateException("Invalid import result mapping key descriptor");String resultId=(String)row.getProperty("resultId"),collection=collectionIdFor(resultId,(String)descriptor.get("collection"));var parts=nodes(ENTRY,Map.of("resultId",resultId,"collectionId",collection));parts.sort(Comparator.comparingLong(n->((Number)n.getProperty("position")).longValue()));var text=new StringBuilder();for(Node part:parts){Object value=Json.read((String)part.getProperty("value"));if(!(value instanceof Map<?,?> chunk)||!"scalar".equals(chunk.get("type"))||!(chunk.get("value") instanceof String segment))throw new IllegalStateException("Invalid import result text segment");text.append(segment);}return text.toString();}
    private int size(long n){return (int)Math.min(Integer.MAX_VALUE,n);}
    private Node lookup(Node collection,String key){return lookup((String)collection.getProperty("id"),(String)collection.getProperty("resultId"),key);}
    private Node lookup(String collectionId,String resultId,String key){String keyHash=hash(key);if(key.getBytes(StandardCharsets.UTF_8).length<=MAX_ENTRY_BYTES/2){Node exact=find(ENTRY,Map.of("resultId",resultId,"collectionId",collectionId,"mapKeyHash",keyHash,"mapKey",key));if(exact!=null)return exact;}for(Node candidate:nodes(ENTRY,Map.of("resultId",resultId,"collectionId",collectionId,"mapKeyHash",keyHash)))if(keyEquals(candidate,key))return candidate;return null;}
    private boolean keyEquals(Node row,String expected){if(row.hasProperty("mapKey"))return expected.equals(row.getProperty("mapKey"));if(((Number)row.getProperty("mapKeyLength",-1)).longValue()!=expected.getBytes(StandardCharsets.UTF_8).length)return false;Object raw=Json.read((String)row.getProperty("key"));if(!(raw instanceof Map<?,?> descriptor)||!"text".equals(descriptor.get("type")))return false;String textCollection=(String)descriptor.get("collection"),resultId=(String)row.getProperty("resultId");var parts=nodes(ENTRY,Map.of("resultId",resultId,"collectionId",collectionIdFor(resultId,textCollection)));parts.sort(Comparator.comparingLong(n->((Number)n.getProperty("position")).longValue()));byte[] wanted=expected.getBytes(StandardCharsets.UTF_8);int offset=0;for(Node part:parts){Object chunkDescriptor=Json.read((String)part.getProperty("value"));if(!(chunkDescriptor instanceof Map<?,?> chunk)||!"scalar".equals(chunk.get("type"))||!(chunk.get("value") instanceof String value))return false;byte[] bytes=value.getBytes(StandardCharsets.UTF_8);if(offset+bytes.length>wanted.length)return false;for(int i=0;i<bytes.length;i++)if(bytes[i]!=wanted[offset+i])return false;offset+=bytes.length;}return offset==wanted.length;}
    private String collectionIdFor(String resultId,String collectionName){Node collection=find(COLLECTION,Map.of("resultId",resultId,"name",collectionName));return collection==null?collectionName:(String)collection.getProperty("id");}
    private Object decodeValue(String encoded){Object value=Json.read(encoded);if(value instanceof Map<?,?> map&&"scalar".equals(map.get("type")))return map.get("value");return value;}
    private Node requireRoot(String id){Node root=find(ROOT,Map.of("id",id));if(root==null)c.fail("NOT_FOUND","Import result is unavailable");return root;}
    private void authorize(Node root){if(!c.namespaceId.equals(root.getProperty("namespaceId"))||!c.actorId.equals(root.getProperty("actorId")))c.fail("NOT_FOUND","Import result is unavailable");String operation=(String)root.getProperty("operationId");Node receipt=find("DepositReceipt",Map.of("scope",c.namespaceId,"operationId",operation));if(receipt==null||!c.actorId.equals(receipt.getProperty("actorId"))||!root.getProperty("id").equals(receipt.getProperty("importResultId",null)))c.fail("NOT_FOUND","Import result is unavailable");}
    private Node find(String label,Map<String,Object> props){try(var found=c.tx.findNodes(Label.label(label),props)){return found.hasNext()?found.next():null;}}
    private List<Node> nodes(String label,Map<String,Object> props){var result=new ArrayList<Node>();try(var found=c.tx.findNodes(Label.label(label),props)){while(found.hasNext())result.add(found.next());}return result;}
    private static String hash(String key){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
